#!/bin/bash

# Optimized Watch Dogs 2 launcher for NVIDIA GTX 1650
# Generated by Antigravity

# Set Wine prefix
WINEPREFIX="$HOME/Applications/Watch Dogs 2/wd2_prefix"
export WINEPREFIX
export WINEARCH=win64

# --- NVIDIA Prime Offload Settings ---
# Force the game to run on the dedicated NVIDIA GPU
export __NV_PRIME_RENDER_OFFLOAD=1
export __GLX_VENDOR_LIBRARY_NAME=nvidia
export __VK_LAYER_NV_optimus=NVIDIA_only
export DRI_PRIME=1
export VK_ICD_FILENAMES=/usr/share/vulkan/icd.d/nvidia_icd.json

# --- DXVK/Vulkan settings ---
# Asynchronous shader compilation to reduce stutter
export DXVK_ASYNC=1
export DXVK_HUD=fps
export DXVK_STATE_CACHE=1
export DXVK_STATE_CACHE_PATH="$HOME/.cache/wine/watchdogs2"

# --- Performance settings ---
# Enable FSR (FidelityFX Super Resolution)
# CRITICAL: This allows you to render at 720p and upscale to 1080p.
# This is essential for smooth performance on the GTX 1650 for this heavy game.
export WINE_FULLSCREEN_FSR=1
export WINE_FULLSCREEN_FSR_STRENGTH=2

# NVIDIA-specific optimizations
export __GL_THREADED_OPTIMIZATIONS=1

# Disable Wine debugging to save CPU cycles
export WINEDEBUG=-all

# --- New Optimizations (Mouse & Lag Fixes) ---
# Enable ESYNC/FSYNC for reduced CPU overhead (Major lag reduction)
export WINEESYNC=1
export WINEFSYNC=1

# Disable NVAPI to prevent stalls (Game doesn't use DLSS, limits overhead)
export WINEDLLOVERRIDES="nvapi,nvapi64=d"

# Force Mouse Warp (Fixes infinite scrolling/camera issues)
export WINE_MOUSE_WARP_OVERRIDE=force

# Create necessary directories
mkdir -p "$HOME/.cache/wine/watchdogs2"

# Change to game directory
cd "/media/rohan/Game/Watch Dogs 2/bin"

# Run the game
echo "Starting Watch Dogs 2 on NVIDIA GPU with FSR (Optimized)..."

# We use gamemoderun to prioritize the game process
# IMPORTANT: Set in-game resolution to 1280x720 for FSR to work!
# Removed virtual desktop to fix mouse bounding issues.
gamemoderun wine WatchDogs2.exe -eac_launcher -dx11
